1: /**
2:  * Safe JSON stringification utility that handles circular references,
3:  * Error objects, and other special types.
4:  */
5: 
6: /**
7:  * Serialize an error object to a plain object with all relevant properties
8:  */
9: function serializeError(error: Error): Record<string, unknown> {
10: 	return {
11: 		message: error.message,
12: 		name: error.name,
13: 		stack: error.stack,
14: 		// Include any additional enumerable properties
15: 		...Object.getOwnPropertyNames(error)
16: 			.filter((key) => key !== "message" && key !== "name" && key !== "stack")
17: 			.reduce(
18: 				(acc, key) => {
19: 					acc[key] = (error as unknown as Record<string, unknown>)[key]
20: 					return acc
21: 				},
22: 				{} as Record<string, unknown>,
23: 			),
24: 	}
25: }
26: 
27: /**
28:  * Safe stringify that handles circular references, Error objects, Dates, RegExp, etc.
29:  * Returns a serializable version of the object.
30:  */
31: export function safeStringify(obj: unknown, seen = new WeakSet()): unknown {
32: 	// Handle primitives
33: 	if (obj === null || typeof obj !== "object") {
34: 		return obj
35: 	}
36: 
37: 	// Handle circular references
38: 	if (seen.has(obj as object)) {
39: 		return "[Circular]"
40: 	}
41: 
42: 	// Handle Error objects
43: 	if (obj instanceof Error) {
44: 		return serializeError(obj)
45: 	}
46: 
47: 	// Handle arrays
48: 	if (Array.isArray(obj)) {
49: 		seen.add(obj)
50: 		const result = obj.map((item) => safeStringify(item, seen))
51: 		seen.delete(obj)
52: 		return result
53: 	}
54: 
55: 	// Handle Date objects
56: 	if (obj instanceof Date) {
57: 		return obj.toISOString()
58: 	}
59: 
60: 	// Handle RegExp objects
61: 	if (obj instanceof RegExp) {
62: 		return obj.toString()
63: 	}
64: 
65: 	// Handle plain objects
66: 	seen.add(obj)
67: 	const result: Record<string, unknown> = {}
68: 	for (const [key, value] of Object.entries(obj)) {
69: 		try {
70: 			result[key] = safeStringify(value, seen)
71: 		} catch (_error) {
72: 			// If serialization fails for a property, mark it
73: 			result[key] = "[Serialization Error]"
74: 		}
75: 	}
76: 	seen.delete(obj)
77: 	return result
78: }
