80: /**
81:  * Convert an argument to a string representation, handling circular references
82:  * and special types. This is specifically designed for console logging.
83:  */
84: export function argToString(arg: unknown): string {
85: 	if (typeof arg === "string") {
86: 		return arg
87: 	}
88: 
89: 	try {
90: 		const safe = safeStringify(arg)
91: 		return JSON.stringify(safe)
92: 	} catch (_error) {
93: 		// Fallback if even safe stringify fails
94: 		return "[Unable to stringify]"
95: 	}
96: }
97: 
98: /**
99:  * Convert multiple arguments to a single string message, handling circular references
100:  */
101: export function argsToMessage(args: unknown[]): string {
102: 	return args.map(argToString).join(" ")
103: }

